#!/usr/bin/env python3
"""Small persistent browser-session authentication for the PuddleDuck web UI.

This is intentionally a local-network authentication layer rather than a full
identity provider. Passwords are stored only as PBKDF2 hashes. Browser sessions
are HMAC-signed cookies and are invalidated whenever the browser password is
changed.
"""

from __future__ import annotations

import argparse
import base64
import hashlib
import hmac
import json
import os
import secrets
import threading
import time
from email.utils import formatdate
from http.cookies import SimpleCookie
from pathlib import Path
from typing import Any, Dict, Optional

AUTH_FILE_VERSION = 1
AUTH_FILE_DEFAULT = "~/.config/puddleduck/web_auth.json"
COOKIE_NAME = "puddleduck_session"
PBKDF2_ITERATIONS = 250_000
SESSION_SECONDS = 180 * 24 * 60 * 60
MIN_PASSWORD_LENGTH = 8
MAX_PASSWORD_LENGTH = 128


def _b64e(value: bytes) -> str:
    return base64.urlsafe_b64encode(value).decode("ascii").rstrip("=")


def _b64d(value: str) -> bytes:
    text = str(value or "")
    return base64.urlsafe_b64decode(text + ("=" * ((4 - len(text) % 4) % 4)))


def validate_browser_password(password: Any) -> str:
    value = str(password or "")
    if any(char in value for char in "\r\n\0"):
        raise ValueError("browser password contains an invalid control character")
    if len(value) < MIN_PASSWORD_LENGTH:
        raise ValueError(f"browser password must contain at least {MIN_PASSWORD_LENGTH} characters")
    if len(value) > MAX_PASSWORD_LENGTH:
        raise ValueError(f"browser password must contain at most {MAX_PASSWORD_LENGTH} characters")
    return value


class BrowserAuthManager:
    """Password hash and stateless signed-cookie manager."""

    def __init__(self, path: Optional[str] = None):
        self.path = Path(os.path.expanduser(path or AUTH_FILE_DEFAULT))
        self._lock = threading.RLock()
        self._data: Dict[str, Any] = {}
        self._mtime_ns: Optional[int] = None
        self._load_error = ""
        self._load()

    def _load(self) -> None:
        with self._lock:
            try:
                raw = self.path.read_text(encoding="utf-8")
            except FileNotFoundError:
                self._data = {}
                self._mtime_ns = None
                self._load_error = ""
                return
            try:
                value = json.loads(raw)
                if not isinstance(value, dict):
                    raise ValueError("authentication file root is not an object")
                if int(value.get("version") or 0) != AUTH_FILE_VERSION:
                    raise ValueError("unsupported authentication file version")
                password = value.get("password")
                if not isinstance(password, dict):
                    raise ValueError("password hash record is missing")
                for key in ("salt", "hash"):
                    if not str(password.get(key) or ""):
                        raise ValueError(f"password {key} is missing")
                if not str(value.get("session_secret") or ""):
                    raise ValueError("session secret is missing")
                self._data = value
                self._load_error = ""
            except Exception as exc:
                # Fail closed when an authentication file exists but is damaged.
                self._data = {"version": AUTH_FILE_VERSION, "corrupt": True}
                self._load_error = f"{type(exc).__name__}: {exc}"
            try:
                self._mtime_ns = self.path.stat().st_mtime_ns
            except OSError:
                self._mtime_ns = None

    def _reload_if_changed(self) -> None:
        try:
            mtime = self.path.stat().st_mtime_ns
        except FileNotFoundError:
            mtime = None
        with self._lock:
            if mtime != self._mtime_ns:
                self._load()

    def configured(self) -> bool:
        self._reload_if_changed()
        with self._lock:
            return bool(self._data)

    def healthy(self) -> bool:
        self._reload_if_changed()
        with self._lock:
            return bool(self._data) and not self._load_error

    def _derive(self, password: str, salt: bytes, iterations: int) -> bytes:
        return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, int(iterations), dklen=32)

    def verify_password(self, password: Any) -> bool:
        self._reload_if_changed()
        with self._lock:
            if not self._data or self._load_error:
                return False
            record = self._data.get("password") or {}
            try:
                salt = _b64d(record["salt"])
                expected = _b64d(record["hash"])
                iterations = int(record.get("iterations") or PBKDF2_ITERATIONS)
                candidate = self._derive(str(password or ""), salt, iterations)
            except Exception:
                return False
            return hmac.compare_digest(candidate, expected)

    def _atomic_save(self, value: Dict[str, Any]) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        temporary = self.path.with_name(self.path.name + ".tmp")
        with temporary.open("w", encoding="utf-8") as stream:
            json.dump(value, stream, indent=2, sort_keys=True)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary, 0o600)
        os.replace(temporary, self.path)
        os.chmod(self.path, 0o600)

    def set_password(self, new_password: Any, *, current_password: Any = None) -> None:
        password = validate_browser_password(new_password)
        self._reload_if_changed()
        with self._lock:
            if self._data:
                if self._load_error:
                    raise RuntimeError(
                        "browser authentication configuration is damaged; reset it from the command line before setting a new password"
                    )
                if not self.verify_password(current_password):
                    raise PermissionError("current browser password is incorrect")
            salt = secrets.token_bytes(16)
            digest = self._derive(password, salt, PBKDF2_ITERATIONS)
            value = {
                "version": AUTH_FILE_VERSION,
                "password": {
                    "algorithm": "pbkdf2-sha256",
                    "iterations": PBKDF2_ITERATIONS,
                    "salt": _b64e(salt),
                    "hash": _b64e(digest),
                },
                # Rotating this secret signs the current browser in while
                # invalidating cookies held by every other browser.
                "session_secret": _b64e(secrets.token_bytes(32)),
                "updated_at": int(time.time()),
            }
            self._atomic_save(value)
            self._data = value
            self._load_error = ""
            self._mtime_ns = self.path.stat().st_mtime_ns

    def _secret(self) -> bytes:
        return _b64d(str(self._data.get("session_secret") or ""))

    def issue_session(self, now: Optional[int] = None) -> str:
        self._reload_if_changed()
        with self._lock:
            if not self._data or self._load_error:
                raise RuntimeError("browser authentication is not configured")
            issued = int(now if now is not None else time.time())
            payload = {
                "v": 1,
                "iat": issued,
                "exp": issued + SESSION_SECONDS,
                "nonce": secrets.token_hex(12),
            }
            raw = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")
            signature = hmac.new(self._secret(), raw, hashlib.sha256).digest()
            return f"{_b64e(raw)}.{_b64e(signature)}"

    def _token_valid(self, token: str, now: Optional[int] = None) -> bool:
        self._reload_if_changed()
        with self._lock:
            if not self._data or self._load_error:
                return False
            try:
                encoded, encoded_signature = str(token or "").split(".", 1)
                raw = _b64d(encoded)
                signature = _b64d(encoded_signature)
                expected = hmac.new(self._secret(), raw, hashlib.sha256).digest()
                if not hmac.compare_digest(signature, expected):
                    return False
                payload = json.loads(raw.decode("utf-8"))
                current = int(now if now is not None else time.time())
                return (
                    isinstance(payload, dict)
                    and int(payload.get("v") or 0) == 1
                    and int(payload.get("iat") or 0) <= current + 300
                    and int(payload.get("exp") or 0) > current
                )
            except Exception:
                return False

    def authenticated(self, cookie_header: Any) -> bool:
        self._reload_if_changed()
        with self._lock:
            if not self._data:
                return True
            if self._load_error:
                return False
        try:
            cookie = SimpleCookie()
            cookie.load(str(cookie_header or ""))
            morsel = cookie.get(COOKIE_NAME)
            token = morsel.value if morsel is not None else ""
        except Exception:
            return False
        return self._token_valid(token)

    def status(self, cookie_header: Any = "") -> Dict[str, Any]:
        self._reload_if_changed()
        with self._lock:
            configured = bool(self._data)
            error = self._load_error
        return {
            "ok": not bool(error),
            "configured": configured,
            "required": configured,
            "authenticated": self.authenticated(cookie_header),
            "session_days": SESSION_SECONDS // (24 * 60 * 60),
            "message": (
                "Browser password is configured."
                if configured and not error
                else (f"Authentication configuration error: {error}" if error else "Browser password is not configured.")
            ),
        }

    @staticmethod
    def cookie_header(token: str) -> str:
        expires = formatdate(time.time() + SESSION_SECONDS, usegmt=True)
        return (
            f"{COOKIE_NAME}={token}; Path=/; Max-Age={SESSION_SECONDS}; "
            f"Expires={expires}; HttpOnly; SameSite=Lax"
        )

    @staticmethod
    def clear_cookie_header() -> str:
        return (
            f"{COOKIE_NAME}=; Path=/; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT; "
            "HttpOnly; SameSite=Lax"
        )

    def reset(self) -> None:
        with self._lock:
            try:
                self.path.unlink()
            except FileNotFoundError:
                pass
            self._data = {}
            self._mtime_ns = None
            self._load_error = ""


class LoginThrottle:
    """Very small in-memory throttle for accidental/brute-force login loops."""

    def __init__(self, limit: int = 6, window_s: int = 60):
        self.limit = max(2, int(limit))
        self.window_s = max(10, int(window_s))
        self._lock = threading.Lock()
        self._failures: Dict[str, list[float]] = {}

    def retry_after(self, key: str) -> int:
        now = time.monotonic()
        with self._lock:
            items = [item for item in self._failures.get(key, []) if now - item < self.window_s]
            self._failures[key] = items
            if len(items) < self.limit:
                return 0
            return max(1, int(self.window_s - (now - items[0])))

    def failed(self, key: str) -> None:
        now = time.monotonic()
        with self._lock:
            items = [item for item in self._failures.get(key, []) if now - item < self.window_s]
            items.append(now)
            self._failures[key] = items

    def succeeded(self, key: str) -> None:
        with self._lock:
            self._failures.pop(key, None)


def _main() -> int:
    parser = argparse.ArgumentParser(description="Inspect or reset PuddleDuck browser authentication")
    parser.add_argument("command", choices=("status", "reset"))
    parser.add_argument("--path", default=AUTH_FILE_DEFAULT)
    args = parser.parse_args()
    manager = BrowserAuthManager(args.path)
    if args.command == "reset":
        manager.reset()
        print("Browser authentication reset. Restart or reload the web service.")
        return 0
    print(json.dumps({**manager.status(), "path": str(manager.path)}, indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(_main())
